<template>
  <div class="page-shell">
    <header class="page-header">
      <div><h1>Pacientes Citados</h1><p>Admisión · Agenda autorizada desde SIGARH</p></div>
      <button class="btn dark" :disabled="!seleccionados.length" @click="abrirBloque"><UIcon name="i-heroicons-arrows-right-left" /> Reprogramar bloque <b v-if="seleccionados.length">({{ seleccionados.length }})</b></button>
    </header>
    <section class="card filters">
      <div class="card-title"><UIcon name="i-heroicons-magnifying-glass" /> Búsqueda</div>
      <div class="filter-grid">
        <input v-model="filtros.dni" placeholder="DNI" /><input v-model="filtros.cuenta" placeholder="Cuenta" /><input v-model="filtros.historia" placeholder="N.° historia" /><input v-model="filtros.apellido" placeholder="Apellido" />
        <input v-model="filtros.desde" type="date" /><input v-model="filtros.hasta" type="date" />
        <select v-model="filtros.medico"><option value="">Todos los médicos</option><option v-for="m in medicos" :key="m.nombre" :value="m.id">{{ m.nombre }}</option></select>
        <select v-model="filtros.estado"><option value="">Todos los estados</option><option value="separada">Separada</option><option value="confirmada">Confirmada</option><option value="atendida">Atendida</option><option value="cancelada">Cancelada</option><option value="no_asistio">No asistió</option></select>
        <button class="btn primary" @click="cargar"><UIcon name="i-heroicons-magnifying-glass" /> Buscar</button><button class="btn ghost" @click="limpiar"><UIcon name="i-heroicons-arrow-path" /> Limpiar</button>
      </div>
    </section>
    <div v-if="error" class="alert">{{ error }}</div>
    <section class="card results">
      <div class="card-title split"><span><UIcon name="i-heroicons-list-bullet" /> Listado de citados</span><span class="count">{{ citas.length }} resultados</span></div>
      <div v-if="cargando" class="state"><UIcon name="i-heroicons-arrow-path" class="spin" /> Cargando citas...</div><div v-else-if="!citas.length" class="state">No se encontraron citas con los filtros indicados.</div>
      <div v-else class="table-wrap"><table><thead><tr><th><input type="checkbox" :checked="todos" @change="marcarTodos" /></th><th>Ticket</th><th>HC</th><th>Cuenta</th><th>Paciente</th><th>Teléfono</th><th>Fecha</th><th>Hora</th><th>Seguro</th><th>Especialidad</th><th>Servicio</th><th>Modalidad</th><th>Médico</th><th>Estado</th><th>Acción</th></tr></thead>
        <tbody><tr v-for="c in citas" :key="c.id" :class="{ selected: seleccionados.includes(c.id) }"><td><input v-model="seleccionados" type="checkbox" :value="c.id" :disabled="['atendida','cancelada'].includes(c.estado)" /></td><td class="mono">{{ ticket(c.id) }}</td><td class="mono">{{ c.paciente_record || '—' }}</td><td class="mono">{{ c.numero_cuenta || '—' }}</td><td class="patient">{{ c.paciente_nombre }}</td><td>{{ c.paciente_telefono || '—' }}</td><td>{{ fecha(c.fecha) }}</td><td class="mono">{{ c.hora_inicio }}</td><td>{{ c.paciente_insurance || c.fuente_financiamiento || '—' }}</td><td>{{ c.especialidad_nombre || '—' }}</td><td>{{ c.servicio_nombre || '—' }}</td><td>{{ c.tipo_consulta || 'PRESENCIAL' }}</td><td>{{ c.medico_nombre || '—' }}</td><td><span class="badge" :class="c.estado">{{ estado(c.estado) }}</span></td><td><div class="actions"><button title="Detalle" @click="ver(c)"><UIcon name="i-heroicons-eye" /></button><button title="Imprimir cita" @click="imprimir(c.id)"><UIcon name="i-heroicons-printer" /></button><button v-if="!['atendida','cancelada'].includes(c.estado)" title="Reprogramar" @click="abrirReprogramar(c)"><UIcon name="i-heroicons-calendar-days" /></button></div></td></tr></tbody>
      </table></div>
    </section>
    <div v-if="modalDetalle" class="overlay" @click.self="modalDetalle=false"><section class="modal detail-modal"><header><h2>Detalle de la cita</h2><button @click="modalDetalle=false">×</button></header><div class="detail-grid"><div><b>Paciente</b><span>{{ actual.paciente_nombre }}</span></div><div><b>N.° cuenta</b><span>{{ actual.numero_cuenta || '—' }}</span></div><div><b>DNI</b><span>{{ actual.paciente_dni || '—' }}</span></div><div><b>Historia clínica</b><span>{{ actual.paciente_record || '—' }}</span></div><div><b>Especialidad</b><span>{{ actual.especialidad_nombre || '—' }}</span></div><div><b>Servicio</b><span>{{ actual.servicio_nombre || '—' }}</span></div><div><b>Médico</b><span>{{ actual.medico_nombre || '—' }}</span></div><div><b>Fecha y hora</b><span>{{ fecha(actual.fecha) }} {{ actual.hora_inicio }}</span></div><div><b>Seguro</b><span>{{ actual.paciente_insurance || actual.fuente_financiamiento || '—' }}</span></div><div><b>Estado</b><span>{{ estado(actual.estado) }}</span></div></div><footer><button class="btn ghost" @click="modalDetalle=false">Cerrar</button><button class="btn primary" @click="imprimir(actual.id)"><UIcon name="i-heroicons-printer" /> Imprimir cita</button></footer></section></div>
    <div v-if="modalReprogramar" class="overlay" @click.self="cerrarReprogramar"><section class="modal"><header><div><h2>{{ modoBloque ? 'Reprogramación en bloque' : 'Reprogramación de cita' }}</h2><p v-if="modoBloque">{{ seleccionados.length }} pacientes seleccionados</p></div><button @click="cerrarReprogramar">×</button></header><div v-if="!modoBloque" class="current"><b>{{ actual.paciente_nombre }}</b><span>{{ fecha(actual.fecha) }} · {{ actual.hora_inicio }} · {{ actual.medico_nombre }}</span></div><label>Fecha destino *</label><input v-model="reprog.fecha" type="date" @change="cargarProgramaciones" /><label>Programación autorizada en SIGARH *</label><select v-model="reprog.programacion" @change="cargarCupos"><option value="">Seleccione médico, especialidad y turno</option><option v-for="p in programaciones" :key="p.id" :value="p.id">{{ p.medico_nombre }} · {{ p.especialidad_nombre || p.servicio_nombre }} · {{ p.turno }} {{ p.hora_inicio }}-{{ p.hora_fin }}</option></select><template v-if="!modoBloque"><label>Cupo libre *</label><select v-model="reprog.cupo"><option value="">Seleccione hora</option><option v-for="c in cupos" :key="c.hora_inicio" :value="`${c.hora_inicio}|${c.hora_fin}`">{{ c.hora_inicio }} - {{ c.hora_fin }}</option></select></template><p v-else class="hint">Se asignarán consecutivamente los primeros {{ seleccionados.length }} cupos libres de la programación.</p><label>Mensaje para el paciente</label><textarea v-model="reprog.mensaje" maxlength="500" rows="3" /><div v-if="modalError" class="alert compact">{{ modalError }}</div><footer><button class="btn ghost" @click="cerrarReprogramar">Cancelar</button><button class="btn primary" :disabled="guardando" @click="guardarReprogramacion">{{ guardando ? 'Reprogramando...' : 'Reprogramar' }}</button></footer></section></div>
  </div>
</template>

<script setup lang="ts">
definePageMeta({ layout: 'app', middleware: ['auth'] })
const { api } = useApi(); const { abrirComprobante } = useCitaPdf(); const hoy = new Date().toISOString().slice(0, 10)
const filtros = reactive({ dni:'', cuenta:'', historia:'', apellido:'', desde:hoy, hasta:hoy, medico:'', estado:'' })
const citas=ref<any[]>([]), seleccionados=ref<string[]>([]), cargando=ref(false), error=ref(''), medicos=ref<any[]>([])
const modalDetalle=ref(false), modalReprogramar=ref(false), modoBloque=ref(false), actual=ref<any>({}), programaciones=ref<any[]>([]), cupos=ref<any[]>([]), guardando=ref(false), modalError=ref('')
const reprog=reactive({ fecha:hoy, programacion:'', cupo:'', mensaje:'' })
const elegibles=computed(()=>citas.value.filter(c=>!['atendida','cancelada'].includes(c.estado))); const todos=computed(()=>elegibles.value.length>0&&elegibles.value.every(c=>seleccionados.value.includes(c.id)))
const ticket=(id:string)=>id?.split('-')[0].toUpperCase(); const fecha=(v:string)=>v?new Date(`${v}T12:00:00`).toLocaleDateString('es-PE'):'—'; const estado=(v:string)=>({separada:'Separada',confirmada:'Confirmada',atendida:'Atendida',cancelada:'Cancelada',no_asistio:'No asistió'} as any)[v]||v
function marcarTodos(e:any){seleccionados.value=e.target.checked?elegibles.value.map(c=>c.id):[]} function ver(c:any){actual.value=c;modalDetalle.value=true} async function imprimir(id:string){try{await abrirComprobante(id)}catch(e:any){error.value=e?.data?.detail||'No se pudo generar el PDF'}}
async function cargar(){cargando.value=true;error.value='';try{const q=new URLSearchParams();Object.entries({fecha_desde:filtros.desde,fecha_hasta:filtros.hasta,dni:filtros.dni,cuenta:filtros.cuenta,historia:filtros.historia,apellido:filtros.apellido,medico_id:filtros.medico,estado:filtros.estado}).forEach(([k,v])=>v&&q.set(k,v));citas.value=await api(`/app/consulta-externa/citas?${q}`);const map=new Map();citas.value.forEach(c=>c.medico_nombre&&map.set(c.medico_nombre,{id:c.medico_id,nombre:c.medico_nombre}));medicos.value=[...map.values()];seleccionados.value=[]}catch(e:any){error.value=e?.data?.detail||'No se pudieron cargar los citados'}finally{cargando.value=false}}
function limpiar(){Object.assign(filtros,{dni:'',cuenta:'',historia:'',apellido:'',desde:hoy,hasta:hoy,medico:'',estado:''});cargar()} function preparar(){Object.assign(reprog,{fecha:hoy,programacion:'',cupo:'',mensaje:''});programaciones.value=[];cupos.value=[];modalError.value='';modalReprogramar.value=true}
function abrirReprogramar(c:any){actual.value=c;modoBloque.value=false;preparar();reprog.fecha=c.fecha||hoy;cargarProgramaciones()} function abrirBloque(){modoBloque.value=true;preparar();cargarProgramaciones()} function cerrarReprogramar(){modalReprogramar.value=false}
async function cargarProgramaciones(){reprog.programacion='';reprog.cupo='';cupos.value=[];if(!reprog.fecha)return;try{programaciones.value=await api(`/app/consulta-externa/programacion-medica?fecha=${reprog.fecha}`)}catch{modalError.value='No se pudo cargar la programación SIGARH'}} async function cargarCupos(){reprog.cupo='';if(!reprog.programacion)return;try{cupos.value=(await api(`/app/consulta-externa/citas/cupos/${reprog.programacion}`)).filter((c:any)=>c.disponible)}catch{modalError.value='No se pudieron cargar los cupos'}}
async function guardarReprogramacion(){modalError.value='';if(!reprog.programacion||(!modoBloque.value&&!reprog.cupo)){modalError.value='Selecciona una programación y un cupo libre';return}guardando.value=true;try{if(modoBloque.value){await api('/app/consulta-externa/citas/acciones/reprogramar-bloque',{method:'POST',body:{cita_ids:seleccionados.value,programacion_medica_id:reprog.programacion,mensaje:reprog.mensaje||null}})}else{const [inicio,fin]=reprog.cupo.split('|');await api(`/app/consulta-externa/citas/${actual.value.id}/reprogramar`,{method:'POST',body:{programacion_medica_id:reprog.programacion,hora_inicio:inicio,hora_fin:fin,mensaje:reprog.mensaje||null}})}modalReprogramar.value=false;await cargar()}catch(e:any){modalError.value=e?.data?.detail||'No se pudo reprogramar'}finally{guardando.value=false}} onMounted(cargar)
</script>

<style scoped>
.page-shell{padding:24px;max-width:1900px;margin:auto;color:var(--ink)}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page-header h1{font-size:28px;font-weight:750}.page-header p{color:var(--ink-soft)}.card{background:var(--paper);border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-bottom:22px}.card-title{padding:14px 18px;font-size:17px;font-weight:700;background:var(--navy);color:white;display:flex;align-items:center;gap:8px}.filters .card-title{background:var(--teal)}.split{justify-content:space-between}.count{font-size:13px;font-weight:500}.filter-grid{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:12px;padding:18px}.filter-grid input,.filter-grid select,.modal input,.modal select,.modal textarea{height:42px;border:1px solid var(--line);border-radius:8px;padding:0 12px;background:white}.modal textarea{height:auto;padding:10px;resize:vertical}.btn{height:42px;border-radius:8px;padding:0 16px;display:inline-flex;align-items:center;justify-content:center;gap:7px;font-weight:650}.primary{background:var(--teal);color:white}.dark{background:var(--navy);color:white}.ghost{border:1px solid var(--line);background:white}.btn:disabled{opacity:.45}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:1500px;font-size:13px}th{background:#f2f6f7;text-align:left;padding:11px 8px;white-space:nowrap}td{border-top:1px solid var(--line);padding:11px 8px;vertical-align:top}.selected{background:#f2fbf8}.patient{font-weight:650}.mono{font-family:monospace}.badge{padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700;text-transform:uppercase;background:#eef2f3}.badge.confirmada{background:#e4f1ff;color:#1769aa}.badge.atendida{background:#e4f7ed;color:#18794e}.badge.separada{background:#fff1d6;color:#9a6100}.badge.cancelada{background:#ffe7e7;color:#b42318}.actions{display:flex;gap:5px}.actions button{width:32px;height:32px;border:1px solid var(--line);border-radius:6px;display:grid;place-items:center;color:var(--navy);background:white}.state{padding:55px;text-align:center;color:var(--ink-soft)}.spin{animation:spin 1s linear infinite}.alert{padding:13px 16px;background:#fee4e2;color:#b42318;border-radius:9px;margin-bottom:14px}.compact{margin:12px 0 0}.overlay{position:fixed;inset:0;background:#102b3bcc;z-index:1000;display:grid;place-items:center;padding:20px}.modal{background:white;border-radius:14px;width:min(720px,96vw);max-height:90vh;overflow:auto;padding:22px;box-shadow:0 24px 70px #0004}.modal header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:18px}.modal h2{font-size:21px;font-weight:750}.modal header p{color:var(--ink-soft);font-size:13px}.modal header>button{font-size:27px}.modal label{display:block;font-weight:650;font-size:13px;margin:13px 0 6px}.modal input,.modal select,.modal textarea{width:100%}.modal footer{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.detail-modal{width:min(900px,96vw)}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line)}.detail-grid div{background:white;padding:14px;display:grid;grid-template-columns:150px 1fr;gap:10px}.detail-grid b{font-size:12px;text-transform:uppercase;color:var(--ink-soft)}.current{display:flex;flex-direction:column;background:#eef7f7;border-radius:9px;padding:13px}.current span,.hint{color:var(--ink-soft);font-size:13px;margin-top:4px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1100px){.filter-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.page-shell{padding:14px}.page-header{align-items:flex-start;gap:12px}.filter-grid,.detail-grid{grid-template-columns:1fr}.detail-grid div{grid-template-columns:1fr}.page-header .btn{font-size:0}.page-header .btn b{font-size:12px}}
</style>
